def outcomes(doc, scope):
    scope_children = scope_nodes(doc, scope)
    task_log_table = None
    queue_running_table = None
    queue_waiting_table = None
    for node in scope_children:
        if node.get('kind') == 'table':
            if ': Task log' in node['title']:
                task_log_table = node
            elif 'Tasks running' in node['title']:
                queue_running_table = node
            elif 'Tasks waiting' in node['title']:
                queue_waiting_table = node

    result = []
    if task_log_table:
        for idx, row in table_rows(task_log_table):
            ev = row['event']
            if ev in ('start', 'finish', 'evict', 'fail'):
                tid = row['task']
                ent = [tid]
                if row['machine'] != '-':
                    ent.append(row['machine'])
                result.append({
                    "time": int(row['time']),
                    "kind": ev,
                    "entities": ent,
                    "value": None,
                    "src": [[task_log_table['node_id'], idx, ['time', 'task', 'event', 'machine']]]
                })
    if queue_running_table:
        for idx, row in table_rows(queue_running_table):
            result.append({
                "time": 1200,
                "kind": "task_running_at_end",
                "entities": [row['task']],
                "value": int(row['remaining']),
                "src": [[queue_running_table['node_id'], idx, ['task', 'machine', 'started', 'remaining']]]
            })
    if queue_waiting_table:
        for idx, row in table_rows(queue_waiting_table):
            result.append({
                "time": 1200,
                "kind": "task_waiting_at_end",
                "entities": [row['task']],
                "value": None,
                "src": [[queue_waiting_table['node_id'], idx, ['task', 'submitted', 'run time']]]
            })
    return result


