# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    WINDOW_LENGTH = params.get("WINDOW_LENGTH", 1200)
    if horizon is None:
        horizon = 1200.0

    machines = {}
    tasks = {}
    submits = []
    fails = {}
    returns = {}

    for inp in inputs:
        if inp['kind'] == 'machine_config':
            mid = inp['entities'][0]
            machines[mid] = {
                'cap_cpu': inp['fields']['CPU'],
                'cap_mem': inp['fields']['memory'],
                'fails_at': inp['fields']['fails_at'],
                'returns_at': inp['fields']['returns_at'],
                'is_up': True,
                'free_cpu': inp['fields']['CPU'],
                'free_mem': inp['fields']['memory'],
                'running': []
            }
            if inp['fields']['fails_at'] is not None:
                fails[mid] = inp['fields']['fails_at']
            if inp['fields']['returns_at'] is not None:
                returns[mid] = inp['fields']['returns_at']
        elif inp['kind'] == 'task_submit':
            tid = inp['entities'][0]
            tasks[tid] = {
                'submit_time': inp['time'],
                'priority': inp['fields']['priority'],
                'req_cpu': inp['fields']['CPU'],
                'req_mem': inp['fields']['memory'],
                'run_time': inp['fields']['run_time'],
                'remaining': inp['fields']['run_time'],
                'state': 'waiting',
                'machine': None,
                'start_time': None
            }
            submits.append((inp['time'], tid))

    sorted_mids = sorted(machines.keys())
    submits.sort(key=lambda x: (x[0], int(x[1].replace('T', ''))))

    queue = []
    results = []
    next_finishes = {}

    def queue_sort_key(tid):
        t = tasks[tid]
        return (-t['priority'], t['submit_time'], int(tid.replace('T', '')))

    min_t = min([0] + [s[0] for s in submits])
    for t in range(min_t, int(horizon) + 1):
        # 1. Finishes
        finishing = [tid for tid in next_finishes if next_finishes[tid] <= t]
        for tid in sorted(finishing, key=lambda x: int(x.replace('T', ''))):
            t_obj = tasks[tid]
            if t_obj['state'] != 'running': continue
            mid = t_obj['machine']
            m = machines[mid]
            m['free_cpu'] += t_obj['req_cpu']
            m['free_mem'] += t_obj['req_mem']
            m['running'].remove(tid)
            t_obj['state'] = 'finished'
            t_obj['machine'] = None
            results.append({"time": t, "kind": "finish", "entities": [tid, mid], "value": None, "src": []})
            del next_finishes[tid]

        # 2. Failures
        for mid in sorted_mids:
            if mid in fails and fails[mid] == t:
                m = machines[mid]
                if m['is_up']:
                    m['is_up'] = False
                    for tid in sorted(m['running'], key=lambda x: int(x.replace('T', ''))):
                        t_obj = tasks[tid]
                        if t_obj['state'] == 'running':
                            m['running'].remove(tid)
                            t_obj['state'] = 'waiting'
                            t_obj['machine'] = None
                            t_obj['remaining'] = t_obj['run_time']
                            t_obj['start_time'] = None
                            queue.append(tid)
                            if tid in next_finishes: del next_finishes[tid]
                            results.append({"time": t, "kind": "fail", "entities": [tid, mid], "value": None, "src": []})

        # 3. Returns
        for mid in sorted_mids:
            if mid in returns and returns[mid] == t:
                m = machines[mid]
                m['is_up'] = True
                m['free_cpu'] = m['cap_cpu']
                m['free_mem'] = m['cap_mem']
                m['running'] = []

        # 4. Submissions
        for t_sub, tid in submits:
            if t_sub == t:
                queue.append(tid)

        # 5. Scheduling round
        reservation = None
        backfill_used_cpu = {mid: 0 for mid in sorted_mids}
        backfill_used_mem = {mid: 0 for mid in sorted_mids}

        sorted_queue = sorted(queue, key=queue_sort_key)
        for tid in sorted_queue:
            if tid not in queue: continue
            t_obj = tasks[tid]
            started = False

            # 5a First Fit
            for mid in sorted_mids:
                m = machines[mid]
                if not m['is_up']: continue
                if reservation and mid == reservation[1]:
                    r_tid, r_mid, r_time = reservation
                    r_obj = tasks[r_tid]
                    cond1 = (t + t_obj['run_time'] <= r_time)
                    cond2 = (m['cap_cpu'] - r_obj['req_cpu'] - backfill_used_cpu[mid] >= t_obj['req_cpu'] and
                             m['cap_mem'] - r_obj['req_mem'] - backfill_used_mem[mid] >= t_obj['req_mem'])
                    if not (cond1 or cond2): continue
                if m['free_cpu'] >= t_obj['req_cpu'] and m['free_mem'] >= t_obj['req_mem']:
                    m['free_cpu'] -= t_obj['req_cpu']
                    m['free_mem'] -= t_obj['req_mem']
                    m['running'].append(tid)
                    t_obj['state'] = 'running'
                    t_obj['machine'] = mid
                    t_obj['start_time'] = t
                    t_obj['remaining'] = t_obj['run_time']
                    next_finishes[tid] = t + t_obj['run_time']
                    if reservation and mid == reservation[1]:
                        backfill_used_cpu[mid] += t_obj['req_cpu']
                        backfill_used_mem[mid] += t_obj['req_mem']
                    results.append({"time": t, "kind": "start", "entities": [tid, mid], "value": None, "src": []})
                    started = True
                    break

            if started:
                queue.remove(tid)
                continue

            # 5b Preemption
            if reservation is None and t_obj['priority'] >= 9:
                for mid in sorted_mids:
                    m = machines[mid]
                    if not m['is_up']: continue
                    candidates = [ct for ct in m['running'] if tasks[ct]['priority'] <= 1]
                    candidates.sort(key=lambda ct: (tasks[ct]['priority'], -tasks[ct]['start_time'], -int(ct.replace('T', ''))))
                    sim_cpu = m['free_cpu']
                    sim_mem = m['free_mem']
                    evicted = []
                    for ct in candidates:
                        if sim_cpu >= t_obj['req_cpu'] and sim_mem >= t_obj['req_mem']: break
                        ct_obj = tasks[ct]
                        sim_cpu += ct_obj['req_cpu']
                        sim_mem += ct_obj['req_mem']
                        evicted.append(ct)
                    if sim_cpu >= t_obj['req_cpu'] and sim_mem >= t_obj['req_mem']:
                        for ct in evicted:
                            ct_obj = tasks[ct]
                            machines[ct_obj['machine']]['free_cpu'] += ct_obj['req_cpu']
                            machines[ct_obj['machine']]['free_mem'] += ct_obj['req_mem']
                            machines[ct_obj['machine']]['running'].remove(ct)
                            ct_obj['state'] = 'waiting'
                            ct_obj['machine'] = None
                            ct_obj['remaining'] = ct_obj['run_time']
                            ct_obj['start_time'] = None
                            queue.append(ct)
                            if ct in next_finishes: del next_finishes[ct]
                            results.append({"time": t, "kind": "evict", "entities": [ct, mid], "value": None, "src": []})
                        m['free_cpu'] -= t_obj['req_cpu']
                        m['free_mem'] -= t_obj['req_mem']
                        m['running'].append(tid)
                        t_obj['state'] = 'running'
                        t_obj['machine'] = mid
                        t_obj['start_time'] = t
                        t_obj['remaining'] = t_obj['run_time']
                        next_finishes[tid] = t + t_obj['run_time']
                        results.append({"time": t, "kind": "start", "entities": [tid, mid], "value": None, "src": []})
                        started = True
                        break
            if started:
                queue.remove(tid)
                continue

            # 5c Reservation
            if reservation is None:
                best_time = float('inf')
                best_mid = None
                for mid in sorted_mids:
                    m = machines[mid]
                    if m['cap_cpu'] < t_obj['req_cpu'] or m['cap_mem'] < t_obj['req_mem']: continue
                    run_fins = [next_finishes[rt] for rt in m['running'] if rt in next_finishes]
                    earliest = t if not run_fins else max(run_fins)
                    if earliest < best_time or (earliest == best_time and (best_mid is None or mid < best_mid)):
                        best_time = earliest
                        best_mid = mid
                if best_mid is not None:
                    reservation = (tid, best_mid, best_time)
            else:
                r_tid, r_mid, r_time = reservation
                m_r = machines[r_mid]
                if m_r['is_up']:
                    r_obj = tasks[r_tid]
                    cond1 = (t + t_obj['run_time'] <= r_time)
                    cond2 = (m_r['cap_cpu'] - r_obj['req_cpu'] - backfill_used_cpu[r_mid] >= t_obj['req_cpu'] and
                             m_r['cap_mem'] - r_obj['req_mem'] - backfill_used_mem[r_mid] >= t_obj['req_mem'])
                    if (cond1 or cond2) and m_r['free_cpu'] >= t_obj['req_cpu'] and m_r['free_mem'] >= t_obj['req_mem']:
                        m_r['free_cpu'] -= t_obj['req_cpu']
                        m_r['free_mem'] -= t_obj['req_mem']
                        m_r['running'].append(tid)
                        t_obj['state'] = 'running'
                        t_obj['machine'] = r_mid
                        t_obj['start_time'] = t
                        t_obj['remaining'] = t_obj['run_time']
                        next_finishes[tid] = t + t_obj['run_time']
                        backfill_used_cpu[r_mid] += t_obj['req_cpu']
                        backfill_used_mem[r_mid] += t_obj['req_mem']
                        results.append({"time": t, "kind": "start", "entities": [tid, r_mid], "value": None, "src": []})
                        started = True
                if not started:
                    for mid in sorted_mids:
                        if mid == r_mid: continue
                        m = machines[mid]
                        if not m['is_up']: continue
                        if m['free_cpu'] >= t_obj['req_cpu'] and m['free_mem'] >= t_obj['req_mem']:
                            m['free_cpu'] -= t_obj['req_cpu']
                            m['free_mem'] -= t_obj['req_mem']
                            m['running'].append(tid)
                            t_obj['state'] = 'running'
                            t_obj['machine'] = mid
                            t_obj['start_time'] = t
                            t_obj['remaining'] = t_obj['run_time']
                            next_finishes[tid] = t + t_obj['run_time']
                            results.append({"time": t, "kind": "start", "entities": [tid, mid], "value": None, "src": []})
                            started = True
                            break
            if started:
                queue.remove(tid)

    if start is not None:
        results = [r for r in results if r['time'] > start]
    return results
